3231. pub open spec fn handle_delete_request(req: DeleteRequest, s: APIServerState) -> (APIServerState, DeleteResponse) {
3232.     if delete_request_admission_check(req, s) is Some {
3233.         // Deletion fails.
3234.         (s, DeleteResponse{res: Err(delete_request_admission_check(req, s)->0)})
3235.     } else {
3236.         // Deletion succeeds.
3237.         let obj = s.resources[req.key];
3238.         if obj.metadata.finalizers is Some && obj.metadata.finalizers->0.len() > 0 {
3239.             // With the finalizer(s) in the object, we cannot immediately delete it from the key-value store.
3240.             // Instead, we set the deletion timestamp of this object.
3241.             // If the object already has a deletion timestamp, then skip.
3242.             //
3243.             // NOTE: Having finalizer(s) is not the only reason that a deletion is postponed. Having a graceful
3244.             // period set in the deletion option is another reason. Currently we do not model the graceful period
3245.             // option so we don't model how the API server checks whether a deletion should be graceful.
3246.             // However, even without a graceful period option, deleting a Pod can still be graceful depending on its
3247.             // spec content (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/apis/core/types.go#L3256)
3248.             // because Pod implements CheckGracefulDelete (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/registry/core/pod/strategy.go#L168).
3249.             // This is irrelevant to application controllers that do not manage pods, and acceptable for verifying
3250.             // low-level built-in controllers because they are supposed to treat terminating pods as non-existing pods.
3251.             if obj.metadata.deletion_timestamp is Some {
3252.                 // A deletion timestamp is already set so no need to bother it.
3253.                 (s, DeleteResponse{res: Ok(())})
3254.             } else {
3255.                 let stamped_obj_with_new_rv = obj.with_deletion_timestamp(deletion_timestamp())
3256.                                                  .with_resource_version(s.resource_version_counter);
3257.                 (APIServerState {
3258.                     // Here we use req.key, instead of stamped_obj.object_ref(), to insert to the map.
3259.                     // This is intended because using stamped_obj.object_ref() will require us to use
3260.                     // the invariant each_object_in_etcd_is_well_formed a lot more frequently:
3261.                     // we need this invariant to convince Verus that the stamped_obj is well formed
3262.                     // so the key we use to insert to the map is the same as req.key.
3263.                     resources: s.resources.insert(req.key, stamped_obj_with_new_rv),
3264.                     resource_version_counter: s.resource_version_counter + 1,
3265.                     ..s
3266.                 }, DeleteResponse{res: Ok(())})
3267.             }
3268.         } else {
3269.             // The object can be immediately removed from the key-value store.
3270.             //
3271.             // NOTE: In some very corner case, the API server *seems* to first updates the object (to update its finalizers)
3272.             // and then deletes the object immediately, which makes the entire Delete operation not atomic.
3273.             // However, this only happens in the orphan or foreground deletion mode, so we do not model this
3274.             // seemingly non-atomic behavior for now.
3275.             // For more details, see how the API server updates the object in the middle of handling deletion requests:
3276.             // https://github.com/kubernetes/kubernetes/blob/v1.30.0/staging/src/k8s.io/apiserver/pkg/registry/generic/registry/store.go#L1009
3277.             (APIServerState {
3278.                 resources: s.resources.remove(req.key),
3279.                 resource_version_counter: s.resource_version_counter + 1,
3280.                 ..s
3281.             }, DeleteResponse{res: Ok(())})
3282.         }
3283.     }
3284. }
