3293. pub open spec fn update_request_admission_check_helper(installed_types: InstalledTypes, name: StringView, namespace: StringView, obj: DynamicObjectView, s: APIServerState) -> Option<APIError> {
3294.     let key = ObjectRef {
3295.         kind: obj.kind,
3296.         namespace: namespace,
3297.         name: name,
3298.     };
3299.     if obj.metadata.name is None {
3300.         // Update fails because the name of the object is not provided
3301.         Some(APIError::BadRequest)
3302.     } else if name != obj.metadata.name->0 {
3303.         // Update fails because the name of the provided object
3304.         // does not match the name sent on the request
3305.         Some(APIError::BadRequest)
3306.     } else if obj.metadata.namespace is Some
3307.         && namespace != obj.metadata.namespace->0 {
3308.         // Update fails because the namespace of the provided object
3309.         // does not match the namespace sent on the request
3310.         Some(APIError::BadRequest)
3311.     } else if !unmarshallable_object(obj, installed_types) {
3312.         // Update fails because the provided object is not well formed
3313.         // TODO: should the error be BadRequest?
3314.         Some(APIError::BadRequest)
3315.     } else if !s.resources.contains_key(key) {
3316.         // Update fails because the object does not exist
3317.         // TODO: check AllowCreateOnUpdate() to see whether to support create-on-update
3318.         Some(APIError::ObjectNotFound)
3319.     } else if obj.metadata.resource_version is None
3320.         && !allow_unconditional_update(key.kind) {
3321.         // Update fails because the object does not provide a rv and unconditional update is not supported
3322.         Some(APIError::Invalid)
3323.     } else if obj.metadata.resource_version is Some
3324.         && obj.metadata.resource_version != s.resources[key].metadata.resource_version {
3325.         // Update fails because the object has a wrong rv
3326.         Some(APIError::Conflict)
3327.     } else if obj.metadata.uid is Some
3328.         && obj.metadata.uid != s.resources[key].metadata.uid {
3329.         // Update fails because the object has a wrong uid
3330.         Some(APIError::Conflict)
3331.     } else {
