3374.         (s, UpdateResponse{res: Err(update_request_admission_check(installed_types, req, s)->0)})
3375.     } else {
3376.         let old_obj = s.resources[req.key()];
3377.         let updated_obj = updated_object(req, old_obj);
3378.         if updated_obj == old_obj {
3379.             // Update is a noop because there is nothing to update
3380.             // so the resource version counter does not increase here,
3381.             // and the resource version of this object remains the same.
3382.             (s, UpdateResponse{res: Ok(old_obj)})
3383.         } else {
3384.             // Update changes something in the object (either in spec or metadata), so we set it a newer resource version,
3385.             // which is the current rv counter.
3386.             let updated_obj_with_new_rv = updated_obj.with_resource_version(s.resource_version_counter);
3387.             if updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types) is Some {
3388.                 // Update fails.
3389.                 (s, UpdateResponse{res: Err(updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types)->0)})
3390.             } else {
3391.                 // Update succeeds.
3392.                 if updated_obj_with_new_rv.metadata.deletion_timestamp is None
3393.                     || (updated_obj_with_new_rv.metadata.finalizers is Some
3394.                         && updated_obj_with_new_rv.metadata.finalizers->0.len() > 0)
3395.                 {
3396.                     // The regular update case, where the object has no deletion timestamp set
3397.                     // or has at least one finalizer.
3398.                     (APIServerState {
3399.                         resources: s.resources.insert(req.key(), updated_obj_with_new_rv),
3400.                         resource_version_counter: s.resource_version_counter + 1, // Advance the rv counter
3401.                         ..s
3402.                     }, UpdateResponse{res: Ok(updated_obj_with_new_rv)})
3403.                 } else {
3404.                     // The delete-during-update case, where the update removes the finalizers from
3405.                     // the object that has a deletion timestamp, so the object needs to be deleted now.
3406.                     //
3407.                     // NOTE: in the actual implementation, when handling an update request,
3408.                     // the API server first applies the update to the object in the key-value store,
3409.                     // then checks whether the object can be deleted.
3410.                     // If so, it continues to delete the object from the key-value store before replying
3411.                     // to the update request.
3412.                     // This means that there is a super short window where the object has been updated in the store
3413.                     // (with a deletion timestamp and without any finalizer), but has not been deleted yet.
3414.                     // This behavior, strictly speaking, makes the entire Update operation not atomic.
3415.                     // We choose to still model the Update operation as an atomic step for simplicity.
3416.                     // This design choice does not affect the correctness of the controller that issues Update
3417.                     // in a blocking manner because the controller will never observe this intermediate state between
3418.                     // the update and deletion.
3419.                     // More generally speaking, this modeling won't affect the correctness of any controller that
3420.                     // treats a terminating object without finalizers as a non-existing object --- a good practice
3421.                     // controllers should follow.
3422.                     //
3423.                     // NOTE: the API server should also check whether the deletion grace period in the metadata
3424.                     // is set to 0 before deleting the object in case of graceful deletion
3425.                     // (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/staging/src/k8s.io/apiserver/pkg/registry/generic/registry/store.go#L533).
3426.                     // Here we omit that condition because graceful deletion is not supported.
3427.                     (APIServerState {
3428.                         resources: s.resources.remove(updated_obj_with_new_rv.object_ref()),
3429.                         resource_version_counter: s.resource_version_counter + 1, // Advance the rv counter
3430.                         ..s
3431.                     }, UpdateResponse{res: Ok(updated_obj_with_new_rv)})
3432.                 }
3433.             }
3434.         }
3435.     }
3436. }
