cat > /tmp/test_init_inv.rs << 'EOF'
use vstd::prelude::*;

fn main() {}

verus! {

pub type StatePred<T> = spec_fn(T) -> bool;
pub type ActionPred<T> = spec_fn(T, T) -> bool;

pub struct Execution<T> {
    pub nat_to_state: spec_fn(nat) -> T,
}

impl<T> Execution<T> {
    pub open spec fn head(self) -> T {
        (self.nat_to_state)(0)
    }

    pub open spec fn head_next(self) -> T {
        (self.nat_to_state)(1)
    }

    pub open spec fn suffix(self, pos: nat) -> Self {
        Execution {
            nat_to_state: |i: nat| (self.nat_to_state)(i + pos),
        }
    }
}

#[verifier(reject_recursive_types(T))]
pub struct TempPred<T> {
    pub pred: spec_fn(Execution<T>) -> bool,
}

impl<T> TempPred<T> {
    pub open spec fn new(pred: spec_fn(Execution<T>) -> bool) -> Self {
        TempPred { pred: pred }
    }

    pub open spec fn satisfied_by(self, execution: Execution<T>) -> bool {
        (self.pred)(execution)
    }

    pub open spec fn implies(self, other: Self) -> Self {
        TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) ==> other.satisfied_by(ex))
    }

    pub open spec fn entails(self, other: Self) -> bool {
        valid(self.implies(other))
    }
}

pub open spec fn lift_state<T>(state_pred: StatePred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| state_pred(ex.head()))
}

pub open spec fn lift_action<T>(action_pred: ActionPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| action_pred(ex.head(), ex.head_next()))
}

pub open spec fn always<T>(temp_pred: TempPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| forall |i: nat| #[trigger] temp_pred.satisfied_by(ex.suffix(i)))
}

pub open spec fn valid<T>(temp_pred: TempPred<T>) -> bool {
    forall |ex: Execution<T>| temp_pred.satisfied_by(ex)
}

proof fn suffix_head_rel<T>(ex: Execution<T>, n: nat)
    ensures ex.suffix(n).head() == (ex.nat_to_state)(n)
{
    // By definition
    assert(ex.suffix(n).head() == (ex.suffix(n).nat_to_state)(0));
    // suffix nat_to_state is |i: nat| (ex.nat_to_state)(i + n)
    // so (ex.suffix(n).nat_to_state)(0) = (ex.nat_to_state)(0 + n) = (ex.nat_to_state)(n)
    assert((ex.suffix(n).nat_to_state)(0) == (ex.nat_to_state)(0 + n));
}

proof fn suffix_head_next_rel<T>(ex: Execution<T>, n: nat)
    ensures ex.suffix(n).head_next() == ex.suffix((n + 1) as nat).head()
{
    assert(ex.suffix(n).head_next() == (ex.suffix(n).nat_to_state)(1));
    assert((ex.suffix(n).nat_to_state)(1) == (ex.nat_to_state)(1 + n));
    suffix_head_rel(ex, (n + 1) as nat);
    assert(ex.suffix((n + 1) as nat).head() == (ex.nat_to_state)(n + 1));
}

proof fn init_invariant_helper<T>(
    ex: Execution<T>,
    init: StatePred<T>,
    next: ActionPred<T>,
    inv: StatePred<T>,
    i: nat,
)
    requires
        forall |s: T| #[trigger] init(s) ==> inv(s),
        forall |s, s_prime: T| inv(s) && #[trigger] next(s, s_prime) ==> inv(s_prime),
        init(ex.head()),
        forall |j: nat| #[trigger] next(ex.suffix(j).head(), ex.suffix(j).head_next()),
    ensures
        inv(ex.suffix(i).head()),
    decreases i
{
